// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.benchmark;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.sail.lmdb.benchmark.LmdbNativeRegretHarness.Measurement;
import org.eclipse.rdf4j.sail.lmdb.benchmark.LmdbNativeRegretHarness.WinnerControl;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeDecisionTestAccess.Captured;
import org.junit.jupiter.api.Test;

/** Unknown upper features must remain explicit without writing nonstandard JSON numbers. */
class LmdbNativeRegretUnknownUpperRenderingTest {

	@Test
	void unknownUpperFeatureRendersAsJsonNullWithoutMakingTheControlComparable() {
		Captured quote = new Captured("row/join dispatch", "nestedLoop", true, true, null,
				5D, Double.POSITIVE_INFINITY, 30D,
				new double[] { 10D, 20D, 1D }, new double[] { 5D, 0D, 0D },
				new double[] { 15D, Double.POSITIVE_INFINITY, Double.MAX_VALUE });
		WinnerControl control = new WinnerControl("nestedLoop", quote, Measurement.NONE, Measurement.NONE, false,
				"incomplete quote; fitEligible=false");

		List<String> rendered = LmdbNativeRegretHarness.renderWinnerControls(Map.of("case", control));
		String[] cells = rendered.get(rendered.size() - 1).split("\t", -1);

		assertThat(rendered.get(0)).contains("fitEligible=false");
		assertThat(cells[7]).isEqualTo("false");
		assertThat(cells[11]).isEqualTo("[10.0, 20.0, 1.0]");
		assertThat(cells[12]).isEqualTo("[5.0, 0.0, 0.0]");
		assertThat(cells[13]).isEqualTo("[15.0, null, " + Double.MAX_VALUE + "]")
				.doesNotContain("Infinity", "NaN");
	}

	@Test
	void finiteUpperFeaturesKeepTheirExactNumericRendering() {
		Captured quote = new Captured("row/join dispatch", "nestedLoop", true, true, null,
				5D, 15D, 10D, new double[] { 10D }, new double[] { 5D }, new double[] { 15D });
		WinnerControl control = new WinnerControl("nestedLoop", quote, Measurement.NONE, Measurement.NONE, false,
				"fitEligible=false");

		List<String> rendered = LmdbNativeRegretHarness.renderWinnerControls(Map.of("case", control));
		String[] cells = rendered.get(rendered.size() - 1).split("\t", -1);

		assertThat(cells[13]).isEqualTo("[15.0]");
	}
}
